--Kalyan on 8/04/11 for CR 45104:Added HR & VHR count attributes --11/12/2009 ADDED TRUSTED PAIR FUNCTIONALITY
/*The subrules are incorrecly recording all transactions now. They should only record either very high risk transacirons or high risk transactions based on the whether the very high risk or high risk thresholds are surpassed.
Suggset (1) adding a variable in the primary rule to flag whether the very high riak or high risk thresholds are surpassed, [vp] what transactions should be marked as surpassed, therefore they will be augmented if both condition below are true , case when (sum(t.Vhr_Lev_Am)>=&Min_Tot_Very_High_Risk_Amt and sum(t.Vhr_Lev_Am)/sum(t.TRXN_BASE_AM)*100>=@Min_Prctg_Of_Tot_Very_High_Risk_Amt) then 'VHRT' when (sum(t.Hr_Lev_Am)>=@Min_Tot_High_Risk_Amt and sum(t.Hr_Lev_Am)/sum(t.TRXN_BASE_AM)*100>=@Min_Prctg_Of_Tot_High_Risk_Amt) then 'HRT' end (2) adding the activity risk number attribute of the focal party in the sub-rule datasets, (3) adding filtering logic into the sub-rules' constraints to only record transactions having focal party activity risk number are greater than or equal to either the Min Very High-Risk Level or Min High-Risk Level threshold. */ select t.Acct_Intrl_Id , count(t.Acct_Intrl_Id) as Trans_Ct , max(t.Acct_Seq_Id) as Acct_Seq_Id , max(Effctv_Risk_Nb) as Effctv_Risk_Nb , sum(t.TRXN_BASE_AM) as Tot_Trans_Amt , sum(t.Hr_Lev_Am)/sum(t.TRXN_BASE_AM)*100 as HR_Trans_Prctg , sum(t.Vhr_Lev_Am)/sum(t.TRXN_BASE_AM)*100 as VHR_Trans_Prctg , sum(t.Hr_Lev_Am)/sum(t.TRXN_BASE_AM)*100 as HR_Prctg , sum(t.Lrf_Am)/sum(t.TRXN_BASE_AM)*100 as Lrf_Prctg , sum(t.Pass_Thru_Am)/sum(t.TRXN_BASE_AM)*100 as Pass_Thru_Prctg , sum(t.Vhr_Lev_Am) as Vhr_Lev_Amt , sum(t.Hr_Lev_Am) as Hr_Lev_Amt , sum(t.Vhr_Lev_Ct) as Tot_Very_High_Risk_Trans_Ct , sum(t.Hr_Lev_Ct) as Tot_High_Risk_Trans_Ct ,sum(Trusted_Trans_Amt) as Trusted_Trans_Amt -- this is important to have this order sub statements , CASE when ( sum(t.Vhr_Lev_Am)>= @Min_Tot_Very_High_Risk_Amt and ( sum(t.Vhr_Lev_Am)/sum(t.TRXN_BASE_AM))*100>= @Min_Prctg_Of_Tot_Very_High_Risk_Amt) and ( sum(t.Hr_Lev_Am) >= @Min_Tot_High_Risk_Amt and ( sum(t.Hr_Lev_Am)/sum(t.TRXN_BASE_AM))*100 >= @Min_Prctg_Of_Tot_High_Risk_Amt) then 'BOTH' when ( sum(t.Vhr_Lev_Am)>=@Min_Tot_Very_High_Risk_Amt and ( sum(t.Vhr_Lev_Am)/sum(t.TRXN_BASE_AM))*100>= @Min_Prctg_Of_Tot_Very_High_Risk_Amt) then 'VHRT' when ( sum(t.Hr_Lev_Am) >= @Min_Tot_High_Risk_Amt and ( sum(t.Hr_Lev_Am)/sum(t.TRXN_BASE_AM))*100 >= @Min_Prctg_Of_Tot_High_Risk_Amt) then 'HRT' end as Passed_Trans_Ty from ( -- ML_HRTransHRCounterParty_AC_Wi -- ----------------------------------------------------------------------------------------------------------- -- ORIGINATOR -- ----------------------------------------------------------------------------------------------------------- select --+ full(w) parallel(w, 2) w.ORIG_ACCT_ID as Acct_Intrl_Id, a.acct_seq_id, a.acct_efctv_risk_nb as Effctv_Risk_Nb, -- w.FO_TRXN_SEQ_ID, w.TRXN_BASE_AM, w.DATA_DUMP_DT, case when w.ORIG_ACTVY_RISK_NB>=@Min_High_Risk_Level then w.TRXN_BASE_AM else 0 end Hr_Lev_Am, case when w.ORIG_ACTVY_RISK_NB>=@Min_Very_High_Risk_Level then w.TRXN_BASE_AM else 0 end Vhr_Lev_Am, -- CR 45104 starts case when w.ORIG_ACTVY_RISK_NB>=@Min_High_Risk_Level then 1 else 0 end Hr_Lev_Ct, case when w.ORIG_ACTVY_RISK_NB>=@Min_Very_High_Risk_Level then 1 else 0 end Vhr_Lev_Ct, -- CR 45104 ends case when w.ORIG_ACTVY_RISK_NB>=@Min_High_Risk_Level AND w.data_dump_dt <= (select b.CLNDR_DT from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.data_dump_dt > (select add_days(b.CLNDR_DT, - @Frequency_Period) from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) then w.TRXN_BASE_AM else 0 end HRT_Frequency, case when w.PASS_THRU_FL = 'Y' then w.TRXN_BASE_AM else 0 end Pass_Thru_Am, case when w.TRXN_BASE_AM - trunc(w.TRXN_BASE_AM, -@Lrf_Digits) = 0 then w.TRXN_BASE_AM when w.RCV_TRXN_ACTVY_AM - trunc(w.RCV_TRXN_ACTVY_AM, -@Lrf_Digits) = 0 then w.TRXN_BASE_AM when w.SEND_TRXN_ACTVY_AM - trunc(w.SEND_TRXN_ACTVY_AM, -@Lrf_Digits) = 0 then w.TRXN_BASE_AM else 0 end Lrf_Am ,case when w.TRSTD_TRXN_FL = 'Y' then w.TRXN_BASE_AM else 0 end as Trusted_Trans_Amt from @BUSINESS@.WIRE_TRXN w inner join @BUSINESS@.ACCT a on w.ORIG_ACCT_ID = a.ACCT_INTRL_ID where w.INTRL_ORIG_ACCT_FL = 'Y' and w.MANTAS_TRXN_PRDCT_CD in (@Incl_Wire_Trxn_Prdct_Type_Lst) and w.MANTAS_TRXN_PURP_CD = 'GENERAL' and (@All_Trans_Src_Fl = 'Y' or w.SRC_SYS_CD IN (@Incl_Trans_Src_Lst)) and w.TRXN_EXCTN_DT <= (select b.clndr_dt from @MANTAS@.KDD_cal b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.TRXN_EXCTN_DT > (select add_days(b.clndr_dt, -@Look_Back_Period) from @MANTAS@.KDD_cal b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.DATA_DUMP_DT <= (select b.CLNDR_DT from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.DATA_DUMP_DT > (select add_days(b.CLNDR_DT, - @Look_Back_Period) from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) -- ------------------------------------------------------------------------------------------------------------- and a.ACCT_EFCTV_RISK_NB<>-2 and a.MANTAS_ACCT_BUS_TYPE_CD in (@Mantas_Bus_Acct_Type_Lst) and (@All_Jurisdictions_Fl = 'Y' OR a.JRSDCN_CD IN (@Incl_Jurisdictions_Lst)) and a.MANTAS_ACCT_HOLDR_TYPE_CD = 'CR' and (@Incl_Rltd_Parties ='Y' or COALESCE (w.UNRLTD_PARTY_FL,'Y') <>'N') and (@Include_Trusted_Trans_FL = 'Y' or COALESCE(w.TRSTD_TRXN_FL,'N') ='N') and w.CXL_PAIR_TRXN_INTRL_ID is null UNION ALL -- ML_HRTransHRCounterParty_AC_Wi2 -- ----------------------------------------------------------------------------------------------------------- -- SCND_ORIGINATOR ( SCND_ORIG <> ORIG ) -- ----------------------------------------------------------------------------------------------------------- select --+ full(w) parallel(w, 2) w.SCND_ORIG_ACCT_ID as Acct_Intrl_Id, a.acct_seq_id, a.acct_efctv_risk_nb as Effctv_Risk_Nb, -- w.FO_TRXN_SEQ_ID, w.TRXN_BASE_AM, w.DATA_DUMP_DT, case when w.SCND_ORIG_ACTVY_RISK_NB>=@Min_High_Risk_Level then w.TRXN_BASE_AM else 0 end Hr_Lev_Am, case when w.SCND_ORIG_ACTVY_RISK_NB>=@Min_Very_High_Risk_Level then w.TRXN_BASE_AM else 0 end Vhr_Lev_Am, -- CR 45104 starts case when w.SCND_ORIG_ACTVY_RISK_NB>=@Min_High_Risk_Level then 1 else 0 end Hr_Lev_Ct, case when w.SCND_ORIG_ACTVY_RISK_NB>=@Min_Very_High_Risk_Level then 1 else 0 end Vhr_Lev_Ct, -- CR 45104 starts case when w.SCND_ORIG_ACTVY_RISK_NB>=@Min_High_Risk_Level AND w.data_dump_dt <= (select b.CLNDR_DT from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.data_dump_dt > (select add_days(b.CLNDR_DT, - @Frequency_Period) from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) then w.TRXN_BASE_AM else 0 end HRT_Frequency, case when w.PASS_THRU_FL = 'Y' then w.TRXN_BASE_AM else 0 end Pass_Thru_Am, case when w.TRXN_BASE_AM - trunc(w.TRXN_BASE_AM, -@Lrf_Digits) = 0 then w.TRXN_BASE_AM when w.RCV_TRXN_ACTVY_AM - trunc(w.RCV_TRXN_ACTVY_AM, -@Lrf_Digits) = 0 then w.TRXN_BASE_AM when w.SEND_TRXN_ACTVY_AM - trunc(w.SEND_TRXN_ACTVY_AM, -@Lrf_Digits) = 0 then w.TRXN_BASE_AM else 0 end Lrf_Am ,case when w.TRSTD_TRXN_FL = 'Y' then w.TRXN_BASE_AM else 0 end as Trusted_Trans_Amt from @BUSINESS@.WIRE_TRXN w inner join @BUSINESS@.ACCT a on w.SCND_ORIG_ACCT_ID = a.ACCT_INTRL_ID where w.INTRL_SCND_ORIG_ACCT_FL = 'Y' and (( w.INTRL_ORIG_ACCT_FL = 'Y' and w.SCND_ORIG_ACCT_ID <> w.ORIG_ACCT_ID ) or w.INTRL_ORIG_ACCT_FL <> 'Y') and w.MANTAS_TRXN_PRDCT_CD in (@Incl_Wire_Trxn_Prdct_Type_Lst) and w.MANTAS_TRXN_PURP_CD = 'GENERAL' and (@All_Trans_Src_Fl = 'Y' or w.SRC_SYS_CD IN (@Incl_Trans_Src_Lst)) and w.TRXN_EXCTN_DT <= (select b.clndr_dt from @MANTAS@.KDD_cal b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.TRXN_EXCTN_DT > (select add_days(b.clndr_dt, -@Look_Back_Period) from @MANTAS@.KDD_cal b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.DATA_DUMP_DT <= (select b.CLNDR_DT from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.DATA_DUMP_DT > (select add_days(b.CLNDR_DT, - @Look_Back_Period) from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) -- ------------------------------------------------------------------------------------------------------------- and a.ACCT_EFCTV_RISK_NB<>-2 and a.MANTAS_ACCT_BUS_TYPE_CD in (@Mantas_Bus_Acct_Type_Lst) and (@All_Jurisdictions_Fl = 'Y' OR a.JRSDCN_CD IN (@Incl_Jurisdictions_Lst)) and a.MANTAS_ACCT_HOLDR_TYPE_CD = 'CR' and (@Incl_Rltd_Parties ='Y' or COALESCE (w.UNRLTD_PARTY_FL,'Y') <>'N') and (@Include_Trusted_Trans_FL = 'Y' or COALESCE(w.TRSTD_TRXN_FL,'N') ='N') and w.CXL_PAIR_TRXN_INTRL_ID is null UNION ALL -- ML_HRTransHRCounterParty_AC_Wi3 -- ----------------------------------------------------------------------------------------------------------- -- BENEF -- ----------------------------------------------------------------------------------------------------------- select --+ full(w) parallel(w, 2) w.BENEF_ACCT_ID as Acct_Intrl_Id, a.acct_seq_id, a.acct_efctv_risk_nb as Effctv_Risk_Nb, -- w.FO_TRXN_SEQ_ID, w.TRXN_BASE_AM, w.DATA_DUMP_DT, case when w.BENEF_ACTVY_RISK_NB>=@Min_High_Risk_Level then w.TRXN_BASE_AM else 0 end Hr_Lev_Am, case when w.BENEF_ACTVY_RISK_NB>=@Min_Very_High_Risk_Level then w.TRXN_BASE_AM else 0 end Vhr_Lev_Am, -- CR 45104 starts case when w.BENEF_ACTVY_RISK_NB>=@Min_High_Risk_Level then 1 else 0 end Hr_Lev_Ct, case when w.BENEF_ACTVY_RISK_NB>=@Min_Very_High_Risk_Level then 1 else 0 end Vhr_Lev_Ct, -- CR 45104 ends case when w.BENEF_ACTVY_RISK_NB>=@Min_High_Risk_Level AND w.data_dump_dt <= (select b.CLNDR_DT from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.data_dump_dt > (select add_days(b.CLNDR_DT, - @Frequency_Period) from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) then w.TRXN_BASE_AM else 0 end HRT_Frequency, case when w.PASS_THRU_FL = 'Y' then w.TRXN_BASE_AM else 0 end Pass_Thru_Am, case when w.TRXN_BASE_AM - trunc(w.TRXN_BASE_AM, -@Lrf_Digits) = 0 then w.TRXN_BASE_AM when w.RCV_TRXN_ACTVY_AM - trunc(w.RCV_TRXN_ACTVY_AM, -@Lrf_Digits) = 0 then w.TRXN_BASE_AM when w.SEND_TRXN_ACTVY_AM - trunc(w.SEND_TRXN_ACTVY_AM, -@Lrf_Digits) = 0 then w.TRXN_BASE_AM else 0 end Lrf_Am ,case when w.TRSTD_TRXN_FL = 'Y' then w.TRXN_BASE_AM else 0 end as Trusted_Trans_Amt from @BUSINESS@.WIRE_TRXN w inner join @BUSINESS@.ACCT a on w.BENEF_ACCT_ID = a.ACCT_INTRL_ID where w.INTRL_BENEF_ACCT_FL = 'Y' and (@All_Trans_Src_Fl = 'Y' or w.SRC_SYS_CD IN (@Incl_Trans_Src_Lst)) and w.MANTAS_TRXN_PRDCT_CD in (@Incl_Wire_Trxn_Prdct_Type_Lst) and w.MANTAS_TRXN_PURP_CD = 'GENERAL' and w.TRXN_EXCTN_DT <= (select b.clndr_dt from @MANTAS@.KDD_cal b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.TRXN_EXCTN_DT > (select add_days(b.clndr_dt, -@Look_Back_Period) from @MANTAS@.KDD_cal b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.DATA_DUMP_DT <= (select b.CLNDR_DT from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.DATA_DUMP_DT > (select add_days(b.CLNDR_DT, - @Look_Back_Period) from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) -- ------------------------------------------------------------------------------------------------------------- and a.ACCT_EFCTV_RISK_NB<>-2 and a.MANTAS_ACCT_BUS_TYPE_CD in (@Mantas_Bus_Acct_Type_Lst) and (@All_Jurisdictions_Fl = 'Y' OR a.JRSDCN_CD IN (@Incl_Jurisdictions_Lst)) and a.MANTAS_ACCT_HOLDR_TYPE_CD = 'CR' and (@Incl_Rltd_Parties ='Y' or COALESCE (w.UNRLTD_PARTY_FL,'Y') <>'N') and (@Include_Trusted_Trans_FL = 'Y' or COALESCE(w.TRSTD_TRXN_FL,'N') ='N') and w.CXL_PAIR_TRXN_INTRL_ID is null UNION ALL -- ML_HRTransHRCounterParty_AC_Wi4 -- ----------------------------------------------------------------------------------------------------------- -- BENEF (SCND_BENEF <> BENEF) -- ----------------------------------------------------------------------------------------------------------- select --+ full(w) parallel(w, 2) w.SCND_BENEF_ACCT_ID as Acct_Intrl_Id, a.acct_seq_id, a.acct_efctv_risk_nb as Effctv_Risk_Nb, -- w.FO_TRXN_SEQ_ID, w.TRXN_BASE_AM, w.DATA_DUMP_DT, case when w.SCND_BENEF_ACTVY_RISK_NB>=@Min_High_Risk_Level then w.TRXN_BASE_AM else 0 end Hr_Lev_Am, case when w.SCND_BENEF_ACTVY_RISK_NB>=@Min_Very_High_Risk_Level then w.TRXN_BASE_AM else 0 end Vhr_Lev_Am, -- CR 45104 starts case when w.SCND_BENEF_ACTVY_RISK_NB>=@Min_High_Risk_Level then 1 else 0 end Hr_Lev_Ct, case when w.SCND_BENEF_ACTVY_RISK_NB>=@Min_Very_High_Risk_Level then 1 else 0 end Vhr_Lev_Ct, -- CR 45104 ends case when w.SCND_BENEF_ACTVY_RISK_NB>=@Min_High_Risk_Level AND w.data_dump_dt <= (select b.CLNDR_DT from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.data_dump_dt > (select add_days(b.CLNDR_DT, - @Frequency_Period) from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) then w.TRXN_BASE_AM else 0 end HRT_Frequency, case when w.PASS_THRU_FL = 'Y' then w.TRXN_BASE_AM else 0 end Pass_Thru_Am, case when w.TRXN_BASE_AM - trunc(w.TRXN_BASE_AM, -@Lrf_Digits) = 0 then w.TRXN_BASE_AM when w.RCV_TRXN_ACTVY_AM - trunc(w.RCV_TRXN_ACTVY_AM, -@Lrf_Digits) = 0 then w.TRXN_BASE_AM when w.SEND_TRXN_ACTVY_AM - trunc(w.SEND_TRXN_ACTVY_AM, -@Lrf_Digits) = 0 then w.TRXN_BASE_AM else 0 end Lrf_Am ,case when w.TRSTD_TRXN_FL = 'Y' then w.TRXN_BASE_AM else 0 end as Trusted_Trans_Amt from @BUSINESS@.WIRE_TRXN w inner join @BUSINESS@.ACCT a on w.SCND_BENEF_ACCT_ID = a.ACCT_INTRL_ID where w.INTRL_SCND_BENEF_ACCT_FL = 'Y' and (( w.INTRL_BENEF_ACCT_FL = 'Y' and w.SCND_BENEF_ACCT_ID <> w.BENEF_ACCT_ID) or w.INTRL_BENEF_ACCT_FL <> 'Y' ) and w.MANTAS_TRXN_PRDCT_CD in (@Incl_Wire_Trxn_Prdct_Type_Lst) and w.MANTAS_TRXN_PURP_CD = 'GENERAL' and (@All_Trans_Src_Fl = 'Y' or w.SRC_SYS_CD IN (@Incl_Trans_Src_Lst)) and w.TRXN_EXCTN_DT <= (select b.clndr_dt from @MANTAS@.KDD_cal b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.TRXN_EXCTN_DT > (select add_days(b.clndr_dt, -@Look_Back_Period) from @MANTAS@.KDD_cal b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.DATA_DUMP_DT <= (select b.CLNDR_DT from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.DATA_DUMP_DT > (select add_days(b.CLNDR_DT, - @Look_Back_Period) from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) -- ------------------------------------------------------------------------------------------------------------- and a.ACCT_EFCTV_RISK_NB<>-2 and a.MANTAS_ACCT_BUS_TYPE_CD in (@Mantas_Bus_Acct_Type_Lst) and (@All_Jurisdictions_Fl = 'Y' OR a.JRSDCN_CD IN (@Incl_Jurisdictions_Lst)) and a.MANTAS_ACCT_HOLDR_TYPE_CD = 'CR' and (@Incl_Rltd_Parties ='Y' or COALESCE (w.UNRLTD_PARTY_FL,'Y') <>'N') and (@Include_Trusted_Trans_FL = 'Y' or COALESCE(w.TRSTD_TRXN_FL,'N') ='N') and w.CXL_PAIR_TRXN_INTRL_ID is null UNION ALL -- ------------------------------------------------------------------------------------------------------- -- REM -- ------------------------------------------------------------------------------------------------------- select --+ full(w) parallel(w, 2) w.REM_ACCT_ID as Acct_Intrl_Id, a.acct_seq_id, a.acct_efctv_risk_nb as Effctv_Risk_Nb, -- w.FO_TRXN_SEQ_ID, w.TRXN_BASE_AM, w.DATA_DUMP_DT, case when w.REM_ACTVY_RISK_NB>=@Min_High_Risk_Level then w.TRXN_BASE_AM else 0 end Hr_Lev_Am, case when w.REM_ACTVY_RISK_NB>=@Min_Very_High_Risk_Level then w.TRXN_BASE_AM else 0 end Vhr_Lev_Am, -- CR 45104 starts case when w.REM_ACTVY_RISK_NB>=@Min_High_Risk_Level then 1 else 0 end Hr_Lev_Ct, case when w.REM_ACTVY_RISK_NB>=@Min_Very_High_Risk_Level then 1 else 0 end Vhr_Lev_Ct, -- CR 45104 ends case when w.REM_ACTVY_RISK_NB>=@Min_High_Risk_Level AND w.data_dump_dt <= (select b.CLNDR_DT from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.data_dump_dt > (select add_days(b.CLNDR_DT, - @Frequency_Period) from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) then w.TRXN_BASE_AM else 0 end HRT_Frequency, case when w.PASS_THRU_FL = 'Y' then w.TRXN_BASE_AM else 0 end Pass_Thru_Am, case when w.TRXN_BASE_AM - trunc(w.TRXN_BASE_AM, -@Lrf_Digits) = 0 then w.TRXN_BASE_AM when w.DEP_TRXN_ACTVY_AM - trunc(w.DEP_TRXN_ACTVY_AM, -@Lrf_Digits) = 0 then w.TRXN_BASE_AM when w.ISSUE_TRXN_ACTVY_AM - trunc(w.ISSUE_TRXN_ACTVY_AM, -@Lrf_Digits) = 0 then w.TRXN_BASE_AM when w.CLR_TRXN_ACTVY_AM - trunc(w.CLR_TRXN_ACTVY_AM, -@Lrf_Digits) = 0 then w.TRXN_BASE_AM else 0 end Lrf_Am ,case when w.TRSTD_TRXN_FL = 'Y' then w.TRXN_BASE_AM else 0 end as Trusted_Trans_Amt from @BUSINESS@.MI_TRXN w inner join @BUSINESS@.ACCT a on w.REM_ACCT_ID = a.ACCT_INTRL_ID where w.INTRL_REM_ACCT_FL = 'Y' and w.MANTAS_TRXN_PURP_CD = 'GENERAL' and w.MANTAS_TRXN_PRDCT_CD in (@Incl_MI_Trxn_Prdct_Type_Lst) and (@All_Trans_Src_Fl = 'Y' or w.SRC_SYS_CD IN (@Incl_Trans_Src_Lst)) and w.MANTAS_ISSUE_DATE <= (select b.clndr_dt from @MANTAS@.KDD_cal b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.MANTAS_ISSUE_DATE > (select add_days(b.clndr_dt, -@Look_Back_Period) from @MANTAS@.KDD_cal b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.DATA_DUMP_DT <= (select b.CLNDR_DT from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.DATA_DUMP_DT > (select add_days(b.CLNDR_DT, - @Look_Back_Period) from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) -- ------------------------------------------------------------------------------------------------------------- and a.ACCT_EFCTV_RISK_NB<>-2 and a.MANTAS_ACCT_BUS_TYPE_CD in (@Mantas_Bus_Acct_Type_Lst) and (@All_Jurisdictions_Fl = 'Y' OR a.JRSDCN_CD IN (@Incl_Jurisdictions_Lst)) and a.MANTAS_ACCT_HOLDR_TYPE_CD = 'CR' and (@Incl_Rltd_Parties ='Y' or COALESCE (w.UNRLTD_PARTY_FL,'Y') <>'N') and (@Include_Trusted_Trans_FL = 'Y' or COALESCE(w.TRSTD_TRXN_FL,'N') ='N') and w.CXL_PAIR_TRXN_INTRL_ID is null UNION ALL --ML_HRTransHRCounterParty_AC_Mi2 -- ------------------------------------------------------------------------------------------------------- -- BENEF -- ------------------------------------------------------------------------------------------------------- select --+ full(w) parallel(w, 2) w.BENEF_ACCT_ID as Acct_Intrl_Id, a.acct_seq_id, a.acct_efct